class Solution:
    def videoStitching(self, clips: List[List[int]], time: int) -> int:
        INF = float('inf')
        dp = [0] + [INF] * time
        for t in range(1, time + 1):
            for s, e in clips:
                if s < t <= e:
                    dp[t] = min(dp[t], dp[s] + 1)
        return dp[time] if dp[time] < INF else -1

