class Solution {
public:
    int videoStitching(vector<vector<int>>& clips, int time) {
        const int INF = 101;
        vector<int> dp(time + 1, INF);
        dp[0] = 0;
        for (int t = 1; t <= time; ++t)
            for (auto& c : clips)
                if (c[0] < t && c[1] >= t)
                    dp[t] = min(dp[t], dp[c[0]] + 1);
        return dp[time] >= INF ? -1 : dp[time];
    }
};

