        final int INF = 101;
        int[] dp = new int[time + 1];
        java.util.Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int t = 1; t <= time; t++)
            for (int[] c : clips)
                if (c[0] < t && c[1] >= t)
                    dp[t] = Math.min(dp[t], dp[c[0]] + 1);
        return dp[time] >= INF ? -1 : dp[time];
    }
}

