class Solution:
    def videoStitching(self, clips: List[List[int]], time: int) -> int:
        clips.sort()
        count, cur_end, farthest = 0, 0, 0
        i, n = 0, len(clips)
        while cur_end < time:
            while i < n and clips[i][0] <= cur_end:
                farthest = max(farthest, clips[i][1])
                i += 1
            if farthest <= cur_end:
                return -1
            cur_end = farthest
            count += 1
        return count

